const expected = env.get('BLE_BRIDGE_TOKEN');
const provided = msg.req && msg.req.headers && msg.req.headers['x-ble-bridge-token'];
if (!expected || provided !== expected) {
    return [null, {...msg, statusCode:401, payload:{error:'Unauthorized'}}];
}
let event = msg.payload;
if (typeof event === 'string') {
    try { event = JSON.parse(event); }
    catch (_) { return [null, {...msg, statusCode:400, payload:{error:'Invalid JSON'}}]; }
}
if (!event || typeof event !== 'object' || typeof event.type !== 'string') {
    return [null, {...msg, statusCode:400, payload:{error:'Invalid event'}}];
}
return [
  {topic: 'ble/' + event.type, payload:event},
  {...msg, statusCode:202, payload:{ok:true}}
];

const event = msg.payload;
if (event.type === 'device_found') {
  const seen = context.get('seen') || {};
  seen[event.address] = {name:event.name, rssi:event.rssi, last_seen:event.time};
  context.set('seen', seen);
}
context.set('last_event', event);
const errors = new Set(['scan_error','connection_error']);
if (errors.has(event.type)) {
  node.status({fill:'red',shape:'ring',text:event.type});
} else if (event.type === 'connected') {
  node.status({fill:'green',shape:'dot',text:'connected ' + event.address});
} else if (event.type === 'scan_complete') {
  node.status({fill:'blue',shape:'dot',text:'scan: ' + event.jk_candidates + ' JK candidates'});
}
return msg;

const e = msg.payload || {};
if (e.type === "connected" || e.type === "disconnected") {
  if (e.address) context.set("rx:" + e.address, "");
  return null;
}
if (e.type !== "raw_notification" || !e.address || typeof e.hex !== "string") return null;
const address = String(e.address).toUpperCase();
const safeHex = e.hex.replace(/[^a-fA-F0-9]/g, "");
if (safeHex.length === 0 || safeHex.length % 2) return null;
const fragment = Buffer.from(safeHex, "hex");
let buffer = Buffer.concat([Buffer.from(context.get("rx:" + address) || "", "hex"), fragment]);
const signature = Buffer.from([0x55, 0xAA, 0xEB, 0x90]);
const valid = [], invalid = [];
let steps = 0;
while (buffer.length >= 4 && steps++ < 24) {
  const start = buffer.indexOf(signature);
  if (start < 0) {
    buffer = buffer.subarray(Math.max(0, buffer.length - 3));
    break;
  }
  if (start > 0) buffer = buffer.subarray(start);
  if (buffer.length < 300) break;
  const frame = buffer.subarray(0, 300);
  const checksum = frame.subarray(0, 299).reduce((sum, val) => (sum + val) & 0xFF, 0);
  if (checksum !== frame[299] || ![1, 2, 3].includes(frame[4])) {
    invalid.push({
      topic: "jk/" + address + "/invalid_frame",
      payload: {address, reason: "invalid_header_type_or_crc", type: frame[4],
        computed_crc: checksum, received_crc: frame[299], preview_hex: frame.subarray(0, 24).toString("hex").toUpperCase()}
    });
    buffer = buffer.subarray(1);
    continue;
  }
  valid.push({
    topic: "jk/" + address + "/frame",
    payload: {address, type: frame[4], sequence: frame[5], frame_length: 300,
      crc_ok: true, raw_hex: frame.toString("hex").toUpperCase(), time: e.time}
  });
  buffer = buffer.subarray(300);
}
if (buffer.length > 350) buffer = buffer.subarray(buffer.length - 3);
context.set("rx:" + address, buffer.toString("hex"));
return [valid.length ? valid : null, invalid.length ? invalid : null];
